-- =====================================================================
-- As imagens do catalogo passam a morar no banco
--
-- Ate aqui `tb_produtos.url_imagem` apontava para os SVG de
-- Front/public/produtos. Agora os bytes vem junto com o dado: quem sobe o
-- projeto tem o catalogo ilustrado sem depender de arquivo servido a parte.
--
-- Esta migration e a unica copia desta arte: os arquivos que a originaram
-- sairam do repositorio. O casamento com o produto e pelo NOME, que passou a
-- ser o unico identificador natural depois que o slug deixou de existir.
--
-- SEGURANCA — por que o banco aceita SVG e a aplicacao nao
--
-- SVG e XML e aceita <script> dentro. Servir um SVG enviado por terceiro na
-- mesma origem da loja daria a ele o mesmo poder que o codigo da propria
-- pagina tem. Estes SVG sao nossos: nascem desta migration, que passa por
-- revisao de codigo, e nao de um formulario de upload.
--
-- Por isso a permissao e assimetrica de proposito:
--
--   * o CHECK desta tabela aceita image/svg+xml, senao a carga abaixo nao
--     entraria;
--   * ImagemDeProduto.TIPOS_ACEITOS NAO aceita — e por ali que passa toda
--     escrita da aplicacao, upload do admin inclusive.
--
-- Resultado: SVG so entra por migration. Se algum dia um upload precisar
-- aceitar SVG, a decisao tera de ser tomada de novo, no lugar certo, e vira
-- acompanhada de sanitizacao — nao herdada por descuido deste arquivo.
--
-- Ao servir estas imagens, o endpoint deve mandar Content-Security-Policy com
-- sandbox e X-Content-Type-Options: nosniff. Vale mesmo para o que nos mesmos
-- gravamos: a barreira que so protege contra o ataque que a gente lembrou nao
-- e barreira.
-- =====================================================================

ALTER TABLE tb_produto_imagens DROP CONSTRAINT ck_produto_imagens_tipo;

ALTER TABLE tb_produto_imagens ADD CONSTRAINT ck_produto_imagens_tipo CHECK (
    tipo_conteudo IN ('image/jpeg','image/png','image/webp','image/avif','image/svg+xml'));

-- Tamanho e hash saem do proprio conteudo, calculados pelo banco. Escrever os
-- dois a mao seria repetir um numero que ja esta ali do lado, com a chance de
-- errar um deles e so descobrir quando o cache do navegador servisse a imagem
-- errada.
INSERT INTO tb_produto_imagens (produto_id, conteudo, tipo_conteudo,
                                tamanho_em_bytes, nome_arquivo, hash_sha256)
SELECT p.id,
       d.conteudo,
       'image/svg+xml',
       octet_length(d.conteudo),
       d.nome_arquivo,
       encode(sha256(d.conteudo), 'hex')
  FROM (VALUES
    ('Abacaxi Pérola', '\'::bytea, 'abacaxi-perola.svg'),
    ('Açúcar Refinado 1kg', '\'::bytea, 'acucar-refinado-1kg.svg'),
    ('Água Mineral 500ml', '\'::bytea, 'agua-mineral-500ml.svg'),
