    ('Amaciante Concentrado 2L', '\'::bytea, 'amaciante-concentrado-2l.svg'),
    ('Arroz Branco Tipo 1 5kg', '\'::bytea, 'arroz-branco-tipo-1-5kg.svg'),
    ('Banana Prata', '\'::bytea, 'banana-prata.svg'),
    ('Batata Inglesa Lavada', '\'::bytea, 'batata-inglesa-lavada.svg'),
    ('Broa de Fubá', '\'::bytea, 'broa-de-fuba.svg'),
    ('Café Torrado e Moído', '\'::bytea, 'cafe-torrado-e-moido.svg'),
    ('Carne Moída Patinho', '\'::bytea, 'carne-moida-patinho.svg'),
    ('Cebola Nacional', '\'::bytea, 'cebola-nacional.svg'),
    ('Cenoura', '\'::bytea, 'cenoura.svg'),
    ('Cerveja Pilsen Lata 350ml', '\'::bytea, 'cerveja-pilsen-lata-350ml.svg'),
    ('Costela Suína', '\'::bytea, 'costela-suina.svg'),
    ('Coxão Mole', '\'::bytea, 'coxao-mole.svg'),
    ('Croissant Folhado', '\'::bytea, 'croissant-folhado.svg'),
    ('Desinfetante 2L', '\'::bytea, 'desinfetante-2l.svg'),
    ('Detergente Neutro 500ml', '\'::bytea, 'detergente-neutro-500ml.svg'),
    ('Esponja Multiuso 3un', '\'::bytea, 'esponja-multiuso-3un.svg'),
    ('Farinha de Trigo 1kg', '\'::bytea, 'farinha-de-trigo-1kg.svg'),
    ('Feijão Carioca 1kg', '\'::bytea, 'feijao-carioca-1kg.svg'),
    ('Filé de Peito de Frango', '\'::bytea, 'file-de-peito-de-frango.svg'),
    ('Frango Inteiro Congelado', '\'::bytea, 'frango-inteiro-congelado.svg'),
