  ) AS d (nome, conteudo, nome_arquivo)
  JOIN tb_produtos p ON p.nome = d.nome;

-- Uma origem so para a foto. Com os bytes no banco, deixar tambem o caminho
-- antigo preenchido criaria a duvida de qual dos dois vale — e a duvida so
-- apareceria no dia em que os dois discordassem.
UPDATE tb_produtos
   SET url_imagem = NULL
 WHERE id IN (SELECT produto_id FROM tb_produto_imagens);
